import{I as m,_ as d,t as o,E as c,e as u,h as y,f as p,g}from"./index-OAZsU8fl.js";import{r as h,j as e}from"./react-B-hu5P_j.js";import{R as v}from"./FolderOpenOutlined-DuFeV2sy.js";var b={icon:{tag:"svg",attrs:{viewBox:"64 64 896 896",focusable:"false"},children:[{tag:"path",attrs:{d:"M916 210H376c-17.7 0-32 14.3-32 32v236H108c-17.7 0-32 14.3-32 32v272c0 17.7 14.3 32 32 32h540c17.7 0 32-14.3 32-32V546h236c17.7 0 32-14.3 32-32V242c0-17.7-14.3-32-32-32zm-504 68h200v200H412V278zm-68 468H144V546h200v200zm268 0H412V546h200v200zm268-268H680V278h200v200z"}}]},name:"build",theme:"outlined"},x=function(t,i){return h.createElement(m,d({},t,{ref:i,icon:b}))},f=h.forwardRef(x);const q={ru:{"raqamli-manbalarni-tahlil-qilish":{title:"Метод анализа цифровых исторических источников",goal:"Формирование у будущих учителей истории умений искать, изучать и анализировать цифровые исторические документы, фотографии, карты, рукописи и архивные материалы и использовать их в учебном процессе.",exampleTopic:"Эпоха Амира Темура по историческим источникам",example:"Учитель предлагает студентам цифровые исторические источники эпохи Амира Темура. Например:",exampleItems:["электронный вариант сочинения «Уложения Темура»;","исторические карты эпохи Амира Темура;","фотографии архитектурных памятников того времени."],steps:["Студенты ищут исторические источники на цифровых платформах.","Определяют автора выбранного источника, время и цель его создания.","Анализируют значение источника для освещения исторических событий.","Сравнивают сведения из нескольких источников.","Готовят краткую презентацию по полученным результатам."],topicTitle:"Узбекская государственность в период правления Амира Темура"},"aqliy-hujum":{title:"Метод анализа исторических проблем на основе мозгового штурма",goal:"Развитие у студентов самостоятельного мышления, умения подходить к проблеме с разных точек зрения, выявлять причины исторических событий и обосновывать своё мнение доказательствами.",exampleTopic:"Формирование независимых государств в Мавераннахре в IX веке",example:"В начале занятия учитель задаёт следующий проблемный вопрос:",question:"По какой причине в IX веке в Мавераннахре усилилась власть местных династий и сформировались независимые государства?",steps:["Учитель ставит проблемный вопрос.","Студенты свободно высказывают свои мнения.","Высказанные мнения записываются на электронной доске или интерактивной платформе.","Студенты распределяют мнения по политическим, экономическим, социальным и культурным факторам.","Каждая группа проверяет своё мнение по цифровым историческим источникам.","На основе доказательств формулируется общий вывод."],topicTitle:"Государства Мавераннахра и Хорасана в IX–XII веках"},"virtual-rekonstruksiya":{title:"Метод виртуальной исторической реконструкции",goal:"Развитие исторического мышления студентов через воссоздание в воображении исторических событий, архитектурных памятников, городов и исторической среды с помощью цифровых технологий.",exampleTopic:"Древний Самарканд — город Афрасиаб",example:"Учитель показывает студентам археологические находки древнего городища Афрасиаб, настенные росписи, исторические карты и материалы 3D-реконструкции.",steps:["Студенты изучают археологические и цифровые источники об Афрасиабе.","Определяют расположение и историческую структуру города.","Представляют облик города по историческим изображениям и археологическим данным.","Создают простую 3D-модель или цифровой макет.","Обосновывают созданную модель историческими источниками."]},"interaktiv-xaritalar":{title:"Метод работы с интерактивными историческими картами",goal:"Обучение географическим особенностям исторических событий, границ государств, военных походов, миграций и торговых путей с помощью цифровых карт.",exampleTopic:"Великий шёлковый путь и его историческое значение",example:"Учитель вместе со студентами изучает основные маршруты Великого шёлкового пути по интерактивной карте.",steps:["Студенты открывают цифровую карту.","Отмечают основные маршруты Великого шёлкового пути.","Определяют расположение Самарканда, Бухары, Хивы, Термеза и других исторических центров.","Изучают экономические и культурные связи, осуществлявшиеся по торговым путям.","Готовят исторический вывод на основе карты."],topicTitle:"Великий шёлковый путь — путь диалога и сотрудничества"},"qiyosiy-tarixiy-tahlil":{title:"Метод сравнительно-исторического цифрового анализа",goal:"Развитие аналитического мышления студентов путём сравнения исторических эпох, государств, политических процессов и деятельности исторических личностей по цифровым источникам.",exampleTopic:"Политическое и экономическое развитие государств Саманидов и Караханидов",example:"Учитель предлагает студентам электронные исторические источники, карты, изображения монет и исторические сведения о двух государствах.",steps:["Студенты изучают цифровые источники о государствах Саманидов и Караханидов.","Анализируют образование и политическое управление государств.","Сравнивают экономическую жизнь, торговлю, культуру и развитие науки.","Размещают сходства и различия в электронной таблице.","Делают вывод на основе сравнительного анализа."],topicTitle:"Государства Мавераннахра и Хорасана в IX–XII веках"},"raqamli-tarixiy-tadqiqot":{title:"Метод цифрового исторического исследования",goal:"Формирование у студентов умений вести самостоятельный исторический поиск, пользоваться электронными библиотеками, цифровыми архивами, научными базами данных и историческими документами.",exampleTopic:"Движение джадидов и его представители",example:"Учитель поручает студентам самостоятельно изучить деятельность представителей движения джадидов по цифровым источникам.",steps:["Студенты ищут в электронных библиотеках литературу о джадидизме.","Изучают цифровые копии исторических газет и журналов.","Собирают сведения о жизни и деятельности представителей джадидов.","Отбирают сведения по достоверности и историческому значению.","Готовят электронный отчёт об исследовании."]},"muammoli-vaziyatlarni-modellashtirish":{title:"Метод моделирования проблемных исторических ситуаций",goal:"Развитие у студентов умений выявлять исторические проблемы, анализировать разные точки зрения, принимать решения с учётом исторических условий и делать аргументированные выводы.",exampleTopic:"Политика централизации государства Амира Темура",example:"Учитель предлагает студентам следующую проблемную ситуацию:",question:"Представьте, что вы советник, участвующий в политических процессах Мавераннахра в XIV веке. В стране царит политическая раздробленность. Какие политические меры вы бы предложили для объединения государства и укрепления центральной власти?",steps:["Студенты изучают политическую ситуацию в Мавераннахре XIV века.","Анализируют исторические карты, письменные источники и электронные материалы.","Выявляют причины возникновения проблемы.","В малых группах разрабатывают альтернативные решения.","Обосновывают свои предложения историческими доказательствами.","Сравнивают с реальными политическими решениями эпохи Амира Темура."],topicTitle:"Узбекская государственность в период правления Амира Темура"},gamifikatsiya:{title:"Метод обучения истории на основе геймификации",goal:"Повышение интереса студентов к истории путём внедрения в учебный процесс игровых элементов, баллов, рейтинга, заданий, соревнований и интерактивных вопросов.",exampleTopic:"Исторические личности в истории Узбекистана",example:"Учитель организует викторину о деятельности исторических личностей с помощью Kahoot, Quizizz или других интерактивных платформ.",steps:["Учитель готовит 15–20 вопросов об исторических личностях.","Студенты подключаются к викторине с телефона или компьютера.","Отвечают на вопросы за отведённое время.","За правильные ответы начисляются баллы.","В конце анализируются результаты и разбираются неверные ответы."]},"raqamli-loyiha":{title:"Метод обучения истории на основе цифрового проекта",goal:"Развитие исследовательской, проектной и методико-организаторской компетенций студентов через самостоятельную или командную разработку цифрового проекта по определённой исторической теме.",exampleTopic:"Великие учёные и их вклад в мировую цивилизацию",example:"Учитель делит студентов на группы. Каждая группа готовит цифровой проект об одном из великих учёных, родившихся в Центральной Азии.",steps:["Студенты выбирают тему проекта.","Собирают сведения в электронных библиотеках и научных источниках.","Изучают жизнь, научную деятельность и наследие исторической личности.","Создают цифровую презентацию, веб-страницу, электронную карту или видеопроект.","Защищают результаты проекта.","Учитель оценивает результаты проекта по установленным критериям."],topicTitle:"Эпоха Возрождения IX–XII веков. Вклад наших предков в мировую цивилизацию"}},en:{"raqamli-manbalarni-tahlil-qilish":{title:"The method of analysing digital historical sources",goal:"To develop in future history teachers the skills of searching for, studying and analysing digital historical documents, photographs, maps, manuscripts and archival materials, and of using them in teaching.",exampleTopic:"The era of Amir Temur through historical sources",example:"The teacher gives students digital historical sources from the era of Amir Temur. For example:",exampleItems:["an electronic copy of the “Temur Tuzuklari” (Institutes of Temur);","historical maps of Amir Temur’s era;","photographs of architectural monuments of that time."],steps:["Students search for historical sources on digital platforms.","They identify the author, the period and the purpose of the chosen source.","They analyse the source’s importance for illuminating historical events.","They compare information from several sources.","They prepare a short presentation based on their findings."],topicTitle:"Uzbek statehood under Amir Temur"},"aqliy-hujum":{title:"The method of analysing historical problems through brainstorming",goal:"To develop students’ independent thinking, their ability to approach a problem from different perspectives, to identify the causes of historical events and to support their views with evidence.",exampleTopic:"The formation of independent states in Transoxiana in the 9th century",example:"At the start of the session the teacher poses the following problem question:",question:"Why did the power of local dynasties grow and independent states form in Transoxiana in the 9th century?",steps:["The teacher presents the problem question.","Students freely express their opinions.","The opinions are written on an electronic board or interactive platform.","Students group the opinions into political, economic, social and cultural factors.","Each group tests its opinion against digital historical sources.","A general conclusion is formed on the basis of the evidence."],topicTitle:"The states of Transoxiana and Khorasan in the 9th–12th centuries"},"virtual-rekonstruksiya":{title:"The method of virtual historical reconstruction",goal:"To develop students’ historical thinking by re-imagining historical events, architectural monuments, cities and the historical environment with the help of digital technologies.",exampleTopic:"Ancient Samarkand — the city of Afrasiab",example:"The teacher shows students archaeological finds from the ancient settlement of Afrasiab, wall paintings, historical maps and 3D reconstruction materials.",steps:["Students study archaeological and digital sources on Afrasiab.","They identify the location and historical structure of the city.","They imagine the appearance of the city from historical images and archaeological data.","They create a simple 3D model or digital mock-up.","They justify the model with historical sources."]},"interaktiv-xaritalar":{title:"The method of working with interactive historical maps",goal:"To teach the geographical features of historical events, state borders, military campaigns, migrations and trade routes with the help of digital maps.",exampleTopic:"The Great Silk Road and its historical significance",example:"The teacher studies the main routes of the Great Silk Road with students on an interactive map.",steps:["Students open the digital map.","They mark the main routes of the Great Silk Road.","They locate Samarkand, Bukhara, Khiva, Termez and other historical centres.","They study the economic and cultural ties carried out along the trade routes.","They prepare a historical conclusion based on the map."],topicTitle:"The Great Silk Road — a road of dialogue and cooperation"},"qiyosiy-tarixiy-tahlil":{title:"The method of comparative-historical digital analysis",goal:"To develop students’ analytical thinking by comparing historical eras, states, political processes and the activities of historical figures using digital sources.",exampleTopic:"The political and economic development of the Samanid and Karakhanid states",example:"The teacher provides students with electronic historical sources, maps, images of coins and historical information on the two states.",steps:["Students study digital sources on the Samanid and Karakhanid states.","They analyse the formation and political administration of the states.","They compare economic life, trade, culture and the development of science.","They place similarities and differences in an electronic table.","They draw a conclusion based on the comparative analysis."],topicTitle:"The states of Transoxiana and Khorasan in the 9th–12th centuries"},"raqamli-tarixiy-tadqiqot":{title:"The method of digital historical research",goal:"To develop in students the skills of conducting independent historical research and of using electronic libraries, digital archives, scientific databases and historical documents.",exampleTopic:"The Jadid movement and its representatives",example:"The teacher asks students to study independently the activities of the Jadid movement’s representatives through digital sources.",steps:["Students search electronic libraries for literature on Jadidism.","They study digital copies of historical newspapers and magazines.","They collect information about the life and work of the Jadid figures.","They sort the information by reliability and historical importance.","They prepare an electronic research report."]},"muammoli-vaziyatlarni-modellashtirish":{title:"The method of modelling problematic historical situations",goal:"To develop students’ ability to identify historical problems, analyse different points of view, make decisions in light of historical conditions and draw well-founded conclusions.",exampleTopic:"Amir Temur’s policy of centralising the state",example:"The teacher presents students with the following problem situation:",question:"Imagine you are an adviser taking part in the political processes of Transoxiana in the 14th century. The country is politically fragmented. What political measures would you propose to unite the state and strengthen central power?",steps:["Students study the political situation in Transoxiana in the 14th century.","They analyse historical maps, written sources and electronic materials.","They identify the causes of the problem.","In small groups they develop alternative solutions.","They justify their proposals with historical evidence.","They compare them with the real political decisions of Amir Temur’s era."],topicTitle:"Uzbek statehood under Amir Temur"},gamifikatsiya:{title:"The method of teaching history through gamification",goal:"To raise students’ interest in history by introducing game elements, points, rankings, tasks, competitions and interactive questions into the learning process.",exampleTopic:"Historical figures in the history of Uzbekistan",example:"Using Kahoot, Quizizz or other interactive platforms, the teacher organises a quiz about the activities of historical figures.",steps:["The teacher prepares 15–20 questions about historical figures.","Students join the quiz from a phone or computer.","They answer the questions within the set time.","Points are awarded for correct answers.","At the end the results are analysed and incorrect answers are explained."]},"raqamli-loyiha":{title:"The method of teaching history through a digital project",goal:"To develop students’ research, design and methodological-organisational competences by guiding them to create an independent or team digital project on a particular historical topic.",exampleTopic:"Great scholars and their contribution to world civilisation",example:"The teacher divides students into groups. Each group prepares a digital project on one of the great scholars who came from Central Asia.",steps:["Students choose the project topic.","They gather information from electronic libraries and scholarly sources.","They study the life, scientific work and legacy of the historical figure.","They create a digital presentation, web page, electronic map or video project.","They defend the results of the project.","The teacher assesses the project results against set criteria."],topicTitle:"The Renaissance of the 9th–12th centuries. Our ancestors’ contribution to world civilisation"}}},l={manba:{tone:"bg-blue-50 text-blue-700",bar:"bg-blue-500"},muammo:{tone:"bg-amber-50 text-amber-700",bar:"bg-amber-500"},vizual:{tone:"bg-emerald-50 text-emerald-700",bar:"bg-emerald-500"},interaktiv:{tone:"bg-violet-50 text-violet-700",bar:"bg-violet-500"}},I=Object.fromEntries(Object.keys(l).map(a=>[a,{...l[a],get label(){return o.t(`methodology.cat.${a}`)}}])),T=[{slug:"raqamli-manbalarni-tahlil-qilish",n:1,title:"Raqamli tarixiy manbalarni tahlil qilish metodi",category:"manba",goal:"Bo‘lajak tarix o‘qituvchilarida raqamli tarixiy hujjatlar, fotosuratlar, xaritalar, qo‘lyozmalar va arxiv materiallarini izlash, o‘rganish, tahlil qilish hamda ulardan dars jarayonida foydalanish ko‘nikmalarini shakllantirish.",exampleTopic:"Amir Temur davri tarixiy manbalar asosida",example:"O‘qituvchi talabalarga Amir Temur davriga oid raqamli tarixiy manbalarni taqdim etadi. Masalan:",exampleItems:["«Temur tuzuklari» asarining elektron nusxasi;","Amir Temur davriga oid tarixiy xaritalar;","o‘sha davr me’moriy obidalari fotosuratlari."],steps:["Talabalar raqamli platformalardan tarixiy manbalarni izlaydi.","Tanlangan manbaning muallifi, yaratilgan davri va maqsadini aniqlaydi.","Manbaning tarixiy voqealarni yoritishdagi ahamiyatini tahlil qiladi.","Bir nechta manbadagi ma’lumotlarni o‘zaro taqqoslaydi.","Olingan natijalar asosida qisqa taqdimot tayyorlaydi."],topic:{slug:"amir-temur-davlati",title:"Amir Temur hukmronligi davrida o‘zbek davlatchiligi"},tools:["sources","museum"]},{slug:"aqliy-hujum",n:2,title:"Aqliy hujum asosida tarixiy muammolarni tahlil qilish metodi",category:"muammo",goal:"Talabalarning mustaqil fikrlash, muammoga turli nuqtayi nazardan yondashish, tarixiy voqealar sabablarini aniqlash va o‘z fikrini dalillar bilan asoslash ko‘nikmalarini rivojlantirish.",exampleTopic:"IX asrda Movarounnahrda mustaqil davlatlarning shakllanishi",example:"O‘qituvchi mashg‘ulot boshida quyidagi muammoli savolni beradi:",question:"Nima sababdan IX asrda Movarounnahrda mahalliy sulolalar hokimiyatining kuchayishi va mustaqil davlatlarning shakllanishi jarayoni yuz berdi?",steps:["O‘qituvchi muammoli savolni taqdim etadi.","Talabalar o‘z fikrlarini erkin bildiradi.","Bildirilgan fikrlar elektron doska yoki interaktiv platformaga yozib boriladi.","Talabalar fikrlarni siyosiy, iqtisodiy, ijtimoiy va madaniy omillarga ajratadi.","Har bir guruh o‘z fikrini raqamli tarixiy manbalar bilan tekshiradi.","Dalillar asosida umumiy xulosa shakllantiriladi."],topic:{slug:"ix-xii-asrlar-tarixi",title:"IX–XII asrlarda Movarounnahr va Xuroson davlatlari"},tools:["sources","lessons"]},{slug:"virtual-rekonstruksiya",n:3,title:"Virtual tarixiy rekonstruksiya metodi",category:"vizual",goal:"Tarixiy voqealar, me’moriy obidalar, shaharlar va tarixiy muhitni raqamli texnologiyalar yordamida qayta tasavvur qilish orqali talabalarning tarixiy tafakkurini rivojlantirish.",exampleTopic:"Qadimgi Samarqand — Afrosiyob shahri",example:"O‘qituvchi talabalarga Afrosiyob qadimiy shaharchasining arxeologik topilmalari, devoriy suratlari, tarixiy xaritalari va 3D rekonstruksiya materiallarini namoyish etadi.",steps:["Talabalar Afrosiyobga oid arxeologik va raqamli manbalarni o‘rganadi.","Shaharning joylashuvi va tarixiy tuzilishini aniqlaydi.","Tarixiy tasvirlar va arxeologik ma’lumotlar asosida shahar ko‘rinishini tasavvur qiladi.","Oddiy 3D model yoki raqamli maket yaratadi.","Yaratilgan modelni tarixiy manbalar bilan asoslaydi."],tools:["museum","explore"]},{slug:"interaktiv-xaritalar",n:4,title:"Interaktiv tarixiy xaritalar bilan ishlash metodi",category:"vizual",goal:"Tarixiy voqealar, davlatlar chegaralari, harbiy yurishlar, migratsiya va savdo yo‘llarining geografik xususiyatlarini raqamli xaritalar yordamida o‘rgatish.",exampleTopic:"Buyuk ipak yo‘li va uning tarixiy ahamiyati",example:"O‘qituvchi talabalar bilan interaktiv xarita orqali Buyuk ipak yo‘lining asosiy yo‘nalishlarini o‘rganadi.",steps:["Talabalar raqamli xaritani ochadi.","Buyuk ipak yo‘lining asosiy yo‘nalishlarini belgilaydi.","Samarqand, Buxoro, Xiva, Termiz va boshqa tarixiy markazlarning joylashuvini aniqlaydi.","Savdo yo‘llari orqali amalga oshirilgan iqtisodiy va madaniy aloqalarni o‘rganadi.","Xarita asosida tarixiy xulosa tayyorlaydi."],topic:{slug:"buyuk-ipak-yoli",title:"Buyuk ipak yo‘li — muloqot va hamkorlik yo‘li"},tools:["explore","sources"]},{slug:"qiyosiy-tarixiy-tahlil",n:5,title:"Qiyosiy-tarixiy raqamli tahlil metodi",category:"manba",goal:"Tarixiy davrlar, davlatlar, siyosiy jarayonlar va tarixiy shaxslar faoliyatini raqamli manbalar asosida qiyoslash orqali talabalarning tahliliy fikrlash qobiliyatini rivojlantirish.",exampleTopic:"Somoniylar va Qoraxoniylar davlatining siyosiy-iqtisodiy taraqqiyoti",example:"O‘qituvchi talabalarga ikki davlatga oid elektron tarixiy manbalar, xaritalar, tangalar tasvirlari va tarixiy ma’lumotlarni taqdim etadi.",steps:["Talabalar Somoniylar va Qoraxoniylar davlatiga oid raqamli manbalarni o‘rganadi.","Davlatlarning tashkil topishi va siyosiy boshqaruvini tahlil qiladi.","Iqtisodiy hayot, savdo, madaniyat va ilm-fan rivojini taqqoslaydi.","O‘xshash va farqli jihatlarni elektron jadvalga joylashtiradi.","Qiyosiy tahlil asosida xulosa chiqaradi."],topic:{slug:"ix-xii-asrlar-tarixi",title:"IX–XII asrlarda Movarounnahr va Xuroson davlatlari"},tools:["sources","explore"]},{slug:"raqamli-tarixiy-tadqiqot",n:6,title:"Raqamli tarixiy tadqiqot metodi",category:"manba",goal:"Talabalarda mustaqil tarixiy izlanish olib borish, elektron kutubxonalar, raqamli arxivlar, ilmiy ma’lumotlar bazalari va tarixiy hujjatlardan foydalanish ko‘nikmalarini shakllantirish.",exampleTopic:"Jadidchilik harakati va uning namoyandalari",example:"O‘qituvchi talabalarga jadidchilik harakati vakillarining faoliyatini raqamli manbalar orqali mustaqil o‘rganishni topshiradi.",steps:["Talabalar elektron kutubxonalardan jadidchilikka oid adabiyotlarni izlaydi.","Tarixiy gazeta va jurnallarning raqamli nusxalarini o‘rganadi.","Jadid namoyandalarining hayoti va faoliyati haqida ma’lumot to‘playdi.","Ma’lumotlarni ishonchliligi va tarixiy ahamiyati bo‘yicha saralaydi.","Elektron tadqiqot hisoboti tayyorlaydi."],tools:["sources","profile"]},{slug:"muammoli-vaziyatlarni-modellashtirish",n:7,title:"Muammoli tarixiy vaziyatlarni modellashtirish metodi",category:"muammo",goal:"Talabalarning tarixiy muammolarni aniqlash, turli nuqtayi nazarlarni tahlil qilish, tarixiy sharoitni hisobga olgan holda qaror qabul qilish va dalillangan xulosa chiqarish qobiliyatini rivojlantirish.",exampleTopic:"Amir Temurning davlatni markazlashtirish siyosati",example:"O‘qituvchi talabalarga quyidagi muammoli vaziyatni taqdim etadi:",question:"Tasavvur qiling, siz XIV asrda Movarounnahrdagi siyosiy jarayonlarda ishtirok etayotgan maslahatchisiz. Mamlakatda siyosiy tarqoqlik mavjud. Davlatni birlashtirish va markaziy hokimiyatni mustahkamlash uchun qanday siyosiy choralarni taklif qilgan bo‘lardingiz?",steps:["Talabalar XIV asrdagi Movarounnahrning siyosiy vaziyatini o‘rganadi.","Tarixiy xaritalar, yozma manbalar va elektron materiallarni tahlil qiladi.","Muammoning kelib chiqish sabablarini aniqlaydi.","Kichik guruhlarda muqobil yechimlarni ishlab chiqadi.","Takliflarini tarixiy dalillar bilan asoslaydi.","Amir Temur davridagi real siyosiy qarorlar bilan qiyoslaydi."],topic:{slug:"amir-temur-davlati",title:"Amir Temur hukmronligi davrida o‘zbek davlatchiligi"},tools:["sources","lessons"]},{slug:"gamifikatsiya",n:8,title:"Gamifikatsiya asosida tarixni o‘qitish metodi",category:"interaktiv",goal:"O‘quv jarayoniga o‘yin elementlari, ball, reyting, topshiriq, musobaqa va interaktiv savollarni joriy etish orqali talabalarning tarix faniga qiziqishini oshirish.",exampleTopic:"O‘zbekiston tarixidagi tarixiy shaxslar",example:"O‘qituvchi Kahoot, Quizizz yoki boshqa interaktiv platformalardan foydalanib, tarixiy shaxslar faoliyatiga oid viktorina tashkil qiladi.",steps:["O‘qituvchi tarixiy shaxslar haqida 15–20 ta savol tayyorlaydi.","Talabalar telefon yoki kompyuter orqali viktorinaga ulanadi.","Savollarga belgilangan vaqt ichida javob beradi.","To‘g‘ri javoblar uchun ball beriladi.","Yakunda natijalar tahlil qilinadi va noto‘g‘ri javoblar izohlanadi."],tools:["assignments"]},{slug:"raqamli-loyiha",n:9,title:"Raqamli loyiha asosida tarixni o‘qitish metodi",category:"interaktiv",goal:"Talabalarni muayyan tarixiy mavzu bo‘yicha mustaqil yoki jamoaviy raqamli loyiha ishlab chiqishga yo‘naltirish orqali ularning tadqiqotchilik, loyihalash va metodik tashkilotchilik kompetensiyalarini rivojlantirish.",exampleTopic:"Buyuk allomalar va ularning jahon sivilizatsiyasiga qo‘shgan hissasi",example:"O‘qituvchi talabalarni guruhlarga ajratadi. Har bir guruh Markaziy Osiyoda yetishib chiqqan buyuk allomalardan biri haqida raqamli loyiha tayyorlaydi.",steps:["Talabalar loyiha mavzusini tanlaydi.","Elektron kutubxona va ilmiy manbalardan ma’lumot to‘playdi.","Tarixiy shaxsning hayoti, ilmiy faoliyati va merosini o‘rganadi.","Raqamli taqdimot, veb-sahifa, elektron xarita yoki videoloyiha yaratadi.","Loyiha natijalarini himoya qiladi.","O‘qituvchi loyiha natijalarini belgilangan mezonlar asosida baholaydi."],topic:{slug:"sharq-uygonish-davri",title:"IX–XII asrlarda Uyg‘onish davri. Ajdodlarimizning jahon sivilizatsiyasiga qo‘shgan hissasi"},tools:["sources","profile"]}],s=(a,t)=>{var r;const i=c();return i==="uz"||(r=q[i][a])==null?void 0:r[t]},w=T.map(a=>{const t={...a};for(const i of["title","goal","exampleTopic","example","exampleItems","question","steps"])a[i]!==void 0&&Object.defineProperty(t,i,{enumerable:!0,get:()=>s(a.slug,i)??a[i]});if(a.topic){const i=a.topic;Object.defineProperty(t,"topic",{enumerable:!0,get:()=>({slug:i.slug,title:s(a.slug,"topicTitle")??i.title})})}return t}),n={sources:{icon:e.jsx(g,{}),to:"/app/sources"},museum:{icon:e.jsx(p,{}),to:"/app/museum"},explore:{icon:e.jsx(y,{}),to:"/app/explore"},lessons:{icon:e.jsx(f,{}),to:"/app/lessons"},assignments:{icon:e.jsx(u,{}),to:"/app/assignments"},profile:{icon:e.jsx(v,{}),to:"/app/profile"}},O=Object.fromEntries(Object.keys(n).map(a=>[a,{...n[a],get label(){return o.t(`methodology.tool.${a}`)},get desc(){return o.t(`methodology.tool.${a}Desc`)}}]));export{I as C,w as M,O as T};
